CREATE TABLE "OtpChallenge" ("id" TEXT NOT NULL, "phone" TEXT NOT NULL, "codeHash" TEXT NOT NULL, "expiresAt" TIMESTAMP(3) NOT NULL, "verifiedAt" TIMESTAMP(3), "attempts" INTEGER NOT NULL DEFAULT 0, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "OtpChallenge_pkey" PRIMARY KEY ("id"));
CREATE INDEX "OtpChallenge_phone_createdAt_idx" ON "OtpChallenge"("phone", "createdAt");
CREATE TABLE "QPayPayment" ("id" TEXT NOT NULL, "tenantId" TEXT NOT NULL, "orderId" TEXT NOT NULL, "invoiceId" TEXT NOT NULL, "paymentId" TEXT, "amount" DECIMAL(12,2) NOT NULL, "status" TEXT NOT NULL DEFAULT 'PENDING', "qrData" TEXT NOT NULL, "callbackRaw" JSONB, "paidAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "QPayPayment_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "QPayPayment_invoiceId_key" ON "QPayPayment"("invoiceId"); CREATE UNIQUE INDEX "QPayPayment_paymentId_key" ON "QPayPayment"("paymentId"); CREATE INDEX "QPayPayment_tenantId_orderId_idx" ON "QPayPayment"("tenantId", "orderId");
CREATE TABLE "EbarimtReceipt" ("id" TEXT NOT NULL, "tenantId" TEXT NOT NULL, "orderId" TEXT NOT NULL, "receiptNo" TEXT NOT NULL, "subtotal" DECIMAL(12,2) NOT NULL, "vat" DECIMAL(12,2) NOT NULL, "total" DECIMAL(12,2) NOT NULL, "status" TEXT NOT NULL DEFAULT 'GENERATED', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "EbarimtReceipt_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "EbarimtReceipt_orderId_key" ON "EbarimtReceipt"("orderId"); CREATE UNIQUE INDEX "EbarimtReceipt_receiptNo_key" ON "EbarimtReceipt"("receiptNo"); CREATE INDEX "EbarimtReceipt_tenantId_createdAt_idx" ON "EbarimtReceipt"("tenantId", "createdAt");
